function answersInOtherTakes(recordId: string, build: BuildState, slotKey?: string): Set<string> {
  const out = new Set<string>();
  for (const [k, id] of Object.entries(build.featPicks ?? {})) {
    if (id !== recordId || k === slotKey) continue;
    for (const [ck, v] of Object.entries(build.featChoices ?? {})) {
      if (v && (ck === k || ck.startsWith(`${k}#`))) out.add(v);
    }
  }
  /* …and the SLOTLESS taking a class feature or subclass option granted — a cloistered cleric's
   * First Doctrine Domain Initiate — whose answer is keyed by feat id, not by slot. Without it a
   * second take could re-choose the domain the doctrine already claimed. */
  const granted = build.grantedFeatChoices?.[recordId];
  if (granted && slotKey) out.add(granted);
  return out;
}
```
(Apply alongside the doctrine-grant fix in finding `doctrine-domain-initiate-swallowed-by-own-pick`; on its own this only greys the duplicate, it does not restore the lost taking.)

